CREATE TEMPORARY VIEW dws_order_${grass_region_without_quote} AS
SELECT 
    user_id
    ,COALESCE(category_tag, 'low gmv') AS category_tag
    ,COALESCE(
        CASE
        WHEN (reporting_module = 'Global Search' and reporting_business_line = 'Search') THEN target_type
        WHEN (source1_reporting_module = 'Global Search' and source1_reporting_business_line = 'Search') THEN source1_target_type
        WHEN (source2_reporting_module = 'Global Search' and source2_reporting_business_line = 'Search') THEN source2_target_type
        END, 'NA'
    )  AS target_type
    ,COALESCE(
        CASE 
        WHEN (reporting_module = 'Global Search' and reporting_business_line = 'Search') THEN sort_type
        WHEN (source1_reporting_module = 'Global Search' and source1_reporting_business_line = 'Search') THEN source1_sort_by
        WHEN (source2_reporting_module = 'Global Search' and source2_reporting_business_line = 'Search') THEN source2_sort_by
        END, 'NA'
    ) AS sort_type
    ,COALESCE(CAST(is_ads AS STRING), 'false') AS is_ads
    ,order_id
    ,a.item_id
    
    ,sum(operation_cnt) as order_cnt
	,sum(place_order_gmv) as gmv
    ,sum(pc2_gmv) as pc2_gmv
FROM 
    srdi_mart.dwd_sr_data_warehouse_platform a 
    LEFT JOIN dim_item_${grass_region_without_quote} b 
        ON a.item_id = b.item_id
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND operation = 'order'
    AND (
            (reporting_module = 'Global Search' and reporting_business_line = 'Search')
            or (source1_reporting_module = 'Global Search' and source1_reporting_business_line = 'Search')
            or (source2_reporting_module = 'Global Search' and source2_reporting_business_line = 'Search')
		)
    AND user_id > 0
GROUP BY 
    1,2,3,4,5,6,7;

