    ,item_id
    ,scenario_tag
    ,target_type
    ,CUBE(is_ads)
UNION ALL 
SELECT
    user_id 
    ,order_id 
    ,item_id
    ,scenario_tag
    ,'__ALL__' AS target_type
    ,COALESCE(is_ads, '__ALL__') AS is_ads

