CREATE TEMPORARY VIEW dws_order_outlier_${grass_region_without_quote} AS
SELECT
    user_id 
    ,a.category_tag
    ,target_type
    ,scenario_tag
    ,a.is_ads

    ,SUM(order_cnt) AS order_cnt
	,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,SUM(if(gmv<=gmv_995pct, order_cnt,0) ) AS order_cnt_995
    ,SUM(if(gmv<=gmv_995pct, gmv,gmv_995pct)) AS gmv_995_overwritre
    ,SUM(if(pc2_gmv<=pc2_gmv_995pct, pc2_gmv,pc2_gmv_995pct)) AS pc2_gmv_995_overwritre
FROM
    dws_order_join_${grass_region_without_quote} a 
    LEFT JOIN gmv_outlier_${grass_region_without_quote} b 
        ON a.is_ads = b.is_ads
        AND a.category_tag = b.category_tag
        AND a.scenario_tag = b.feature_group
GROUP BY 
    1,2,3,4,5;

