    ,exp_type

    ,SUM(order_cnt) AS order_cnt
    ,SUM(IF(order_cnt >0 ,1, 0)) AS order_uu
	,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,SUM(order_cnt_995) AS order_cnt_995_v2
    ,SUM(gmv_995_overwritre) AS gmv_995_v2
    ,SUM(pc2_gmv_995_overwritre) AS pc2_gmv_995_v2
FROM 
    dws_order_outlier_${grass_region_without_quote} a 
    INNER JOIN user_exp_mapping_${grass_region_without_quote} b
    ON a.user_id = b.user_id 
GROUP BY 
    1,2,3,4,5,6;

