INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_platform_abtest_category_type_metrics_1d
PARTITION 
(
    grass_region = ${grass_region}, 
    local_date = ${local_date},
    exp_type
)
SELECT 
/*+REPARTITION(2)*/
    COALESCE(a.scenario_tag, b.scenario_tag) AS feature_group
    ,COALESCE(a.exp_group_id, b.exp_group_id) AS exp_group_id
    ,COALESCE(a.category_tag, b.category_tag) AS category_type
    ,COALESCE(a.is_ads, b.is_ads) AS is_ads
    ,COALESCE(a.target_type, b.target_type) AS target_type
    ,'__ALL__' AS sort_type

    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,order_cnt_995_v2
    ,gmv_995_v2
    ,pc2_gmv_995_v2

    ,imp_uu
    ,click_uu
    ,ppv_uu
    ,cart_uu
    ,order_uu
    ,COALESCE(a.exp_type, b.exp_type) AS exp_type
FROM
    exp_metrics_${grass_region_without_quote} a
    FULL OUTER JOIN dws_order_exp_${grass_region_without_quote} b
        ON a.exp_group_id = b.exp_group_id
        AND a.category_tag = b.category_tag
        AND a.is_ads = b.is_ads
        AND a.target_type = b.target_type
        AND a.scenario_tag = b.scenario_tag
        AND a.exp_type = b.exp_type
;

