                    'DA_DD_PP Unify','DA_Search_RCMD'
                )
            )) > 0
        )
    UNION ALL
    SELECT
        user_id
        ,'__ALL__' AS target_type
        ,COALESCE(CAST(is_ads AS STRING), 'false') AS is_ads
        ,array_union(array_union(COALESCE(scenario_tags,array()), COALESCE(source1_scenario_tags,array())), COALESCE(source2_scenario_tags,array())) AS scenario_tags
        ,exp_group_ids
        ,item_id
        ,imp_cnt
        ,click_cnt
