    ,'__ALL__' AS target_type
    ,exp_group_ids
    ,COALESCE(is_ads, '__ALL__') AS is_ads

    ,SUM(order_cnt) AS order_cnt
	,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM 
    dwd_order_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(union_algo_tags) AS scenario_tag
WHERE
    is_da_tag = true
    AND scenario_tag IN (
        'dpm module Global Search business line Search',
        'DA_Daily Discover','DA_You May Also Like','DA_Cart_Unify','DA_Buy Again (Me Page)',
        'DA_Cart Recommendation','DA_odp_ymal-order_detail','DA_Order Successful Recommendation',
        'DA_mpp_ymal-order_list','DA_Me YMAL','DA_Shop YMAL','DA_YMAL_Cart','DA_Shop_Unify','DA_RCMD Unify','DA_OOS',
        'DA_DD_PP Unify','DA_Search_RCMD'
    )
GROUP BY 
    user_id 
    ,order_id 
    ,item_id
    ,scenario_tag
    ,exp_group_ids
    ,CUBE(is_ads)
UNION ALL
SELECT
    user_id
    ,order_id 
    ,item_id
    ,'__ALL__' AS scenario_tag
    ,'__ALL__' AS target_type
    ,exp_group_ids
    ,COALESCE(is_ads, '__ALL__') AS is_ads

    ,SUM(order_cnt) AS order_cnt
	,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM 
    dwd_order_${grass_region_without_quote}
GROUP BY 
    user_id 
    ,order_id 
    ,item_id
    ,exp_group_ids
    ,CUBE(is_ads);

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_order_join_${grass_region_without_quote} AS
SELECT 
    user_id
    ,COALESCE(category_tag, 'low gmv') AS category_tag
    ,scenario_tag
    ,COALESCE(target_type, 'NA') AS target_type
    ,is_ads
    ,order_id
    ,a.item_id
    ,exp_group_ids
    
    ,order_cnt
	,gmv
    ,pc2_gmv
FROM 
    dws_order_cube_${grass_region_without_quote} a 
    LEFT JOIN dim_item_${grass_region_without_quote} b 
        ON a.item_id = b.item_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_order_explode_${grass_region_without_quote} AS
SELECT
    exp_group_id 
    ,category_tag
    ,target_type
    ,scenario_tag
    ,is_ads
    ,order_id
    ,a.item_id
    ,user_id

    ,SUM(order_cnt) AS order_cnt
	,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM 
    dws_order_join_${grass_region_without_quote} a 
    LATERAL VIEW EXPLODE(exp_group_ids) AS exp_group_id
GROUP BY 
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

cache table dws_order_exp_${grass_region_without_quote} AS
SELECT
    a.exp_group_id 
    ,a.category_tag
    ,target_type
    ,a.scenario_tag
    ,a.is_ads

    ,SUM(order_cnt) AS order_cnt
    ,count(distinct IF(order_cnt >0 ,user_id, 0)) AS order_uu
	,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,SUM(if(gmv<=gmv_995pct, order_cnt,0) ) AS order_cnt_995_v2
    ,SUM(if(gmv<=gmv_995pct, gmv,gmv_995pct)) AS gmv_995_v2
    ,SUM(if(pc2_gmv<=pc2_gmv_995pct, pc2_gmv,pc2_gmv_995pct)) AS pc2_gmv_995_v2
FROM 
    dws_order_explode_${grass_region_without_quote} a 
    INNER JOIN exp_filter_${grass_region_without_quote} b 
    ON a.exp_group_id = b.exp_group_id
    LEFT JOIN gmv_outlier_${grass_region_without_quote} c 
        ON a.is_ads = c.is_ads
        AND a.category_tag = c.category_tag
        AND a.scenario_tag = c.feature_group
GROUP BY 
    1,2,3,4,5;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_platform_abtest_category_type_metrics_1d
PARTITION 
(
    grass_region = ${grass_region}, 
    local_date = ${local_date},
    exp_type = 'traffic'
)
SELECT /*+REPARTITION(2)*/
    COALESCE(a.scenario_tag, b.scenario_tag) AS feature_group
    ,COALESCE(a.exp_group_id, b.exp_group_id) AS exp_group_id
    ,COALESCE(a.category_tag, b.category_tag) AS category_type
    ,COALESCE(a.is_ads, b.is_ads) AS is_ads
    ,COALESCE(a.target_type, b.target_type) AS target_type
    ,'__ALL__' AS sort_type

    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,order_cnt_995_v2
    ,gmv_995_v2
    ,pc2_gmv_995_v2

    ,imp_uu
    ,click_uu
    ,ppv_uu
    ,cart_uu
    ,order_uu
FROM
    exp_metrics_${grass_region_without_quote} a
    FULL OUTER JOIN dws_order_exp_${grass_region_without_quote} b
        ON a.exp_group_id = b.exp_group_id
        AND a.category_tag = b.category_tag
        AND a.is_ads = b.is_ads
        AND a.target_type = b.target_type
        AND a.scenario_tag = b.scenario_tag;
